package com.rikkeibank.notification.web;import com.rikkeibank.common.api.BusinessException;import com.rikkeibank.notification.domain.Notification;import com.rikkeibank.notification.repo.NotificationRepository;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/notifications")public class NotificationController{private final NotificationRepository repo;public NotificationController(NotificationRepository r){repo=r;}@GetMapping("/me")@PreAuthorize("hasRole('CUSTOMER')")List<Notification>mine(@AuthenticationPrincipal Jwt jwt){return repo.findByCustomerIdOrderByCreatedAtDesc(UUID.fromString(jwt.getClaimAsString("customerId")));}@GetMapping@PreAuthorize("hasRole('ADMIN')")List<Notification>all(){return repo.findAll();}@PatchMapping("/{id}/read")@PreAuthorize("hasRole('CUSTOMER')")@Transactional Notification read(@PathVariable UUID id,@AuthenticationPrincipal Jwt jwt){Notification n=repo.findById(id).orElseThrow(()->BusinessException.notFound("Notification not found"));if(!n.getCustomerId().toString().equals(jwt.getClaimAsString("customerId")))throw new BusinessException(org.springframework.http.HttpStatus.FORBIDDEN,"ACCESS_DENIED","Not your notification");n.markRead();return n;}}

